initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Batch Request Entities From File with Response Status Code set to 400     and
        Batch Request Entities From File with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/InvalidRequest'     and
        Batch Request Entities From File with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entityOperations/delete'
        method set to 'POST'
        Batch Entity Delete Request with operation set to 'delete', Content-Type set to 'application/ld+json', and body set to 'batch/invalid-json-sample.jsonld
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Batch Request Entities From File with Response Status Code set to 400     and
        Batch Request Entities From File with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Batch Request Entities From File with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entityOperations/delete'
        method set to 'POST'
        Batch Entity Delete Request with operation set to 'delete', Content-Type set to 'application/ld+json', and body set to 'batch/empty-sample.jsonld
}
